mapper.select:
select s.student_id as "studentId", s.student_name as "studentName", s.dept_id as "deptId", case when coalesce(sum(st.attempt_count), 0) > 0 then sum(st.weighted_rate * st.attempt_count) / sum(st.attempt_count) else avg(st.weighted_rate) end as "metricValue", max(st.subject_id) as "subjectId" from spas_student s join spas_student_knowledge_stat st on st.student_id = s.student_id where s.del_flag = '0' and s.status = '0' AND st.subject_id = #{subjectId}
AND (s.dept_id = #{deptId} OR s.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE cast(#{deptId} as varchar) = any(string_to_array(t.ancestors, ',')) ))
group by s.student_id, s.student_name, s.dept_id

select s.student_id as "studentId", s.student_name as "studentName", s.dept_id as "deptId", count(*)::numeric as "metricValue", max(st.subject_id) as "subjectId" from spas_student s join spas_student_knowledge_stat st on st.student_id = s.student_id where s.del_flag = '0' and s.status = '0' and st.weak_level in ('2', '3') AND st.subject_id = #{subjectId}
AND (s.dept_id = #{deptId} OR s.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE cast(#{deptId} as varchar) = any(string_to_array(t.ancestors, ',')) ))
group by s.student_id, s.student_name, s.dept_id

with stu as ( select s.student_id, s.student_name, s.dept_id, case when coalesce(sum(st.attempt_count), 0) > 0 then sum(st.weighted_rate * st.attempt_count) / sum(st.attempt_count) else avg(st.weighted_rate) end as stu_rate, max(st.subject_id) as subject_id from spas_student s join spas_student_knowledge_stat st on st.student_id = s.student_id where s.del_flag = '0' and s.status = '0' AND st.subject_id = #{subjectId}
AND (s.dept_id = #{deptId} OR s.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE cast(#{deptId} as varchar) = any(string_to_array(t.ancestors, ',')) ))
group by s.student_id, s.student_name, s.dept_id ), cls as ( select dept_id, avg(stu_rate) as class_rate from stu group by dept_id ) select stu.student_id as "studentId", stu.student_name as "studentName", stu.dept_id as "deptId", (cls.class_rate - stu.stu_rate) as "metricValue", stu.subject_id as "subjectId" from stu join cls on cls.dept_id = stu.dept_id where cls.class_rate is not null
